// test/fixtures/甘特合成台账.js — CX-11 判据基座：四层树甘特的合成台账（程序化生成，2026-08-24）
//
// 施工令《方案-甘特表现层重做-2026-08-24》第五章判据基座条：
// 「立一份合成台账（四层含缺父孤儿、20 张同刻钟并发子单、越线单两分支、外部依赖+循环依赖、500 行规模），
//   每期端到端跑同一份台账断言行为」。本文件就是那份台账——**函数程序化生成，不落几百行 JSON**。
//
// 形状纪律（P0-0 契约冻结，四口 API 真实响应形逐口对拍）：
//   管线    ← GET /api/pipelines（server.js:461，[{id, ...fm}]）
//   特性    ← GET /api/features（server.js:491，features.聚合 输出形）
//   专项    ← GET /api/specials（server.js:531，specials.聚合 输出形；子单 明细由本台账按单号回填——
//             但树的工单行数据源是 粒+board单，专项.子单 只是聚合快照，岛不许拿它当第二数据源）
//   粒      ← GET /api/schedule（server.js:1249，schedule.现态 形 + 判定 嵌入。判定一律**真调**
//             lib/pm/schedule.工期判定 生成——唯 g-判锁 例外：它的判定故意与前端可私算值分叉，
//             用来锁「只画不判」（判据⑦）：卡上跟着服务端走才绿，自算 e−基线 必红）
//   边/边统计 ← GET /api/schedule 增发（P0-0 裁决④ **已落地**，server.js:1275）：真调
//             lib/pm/schedule-edges.边集 生成（服务端唯一实现产边，夹具不手搓第二套解析，
//             同 判定 真调 工期判定 的纪律）。前端只按下发的 外部/冲突/环 着色，一律不自算。
//   board单 ← GET /api/board 的 board（state→数组；fm.特性 已按 P0-0 裁决② 补格，server.js:279）
// 粒ID 真实形是 UUID；台账用可读串（g-xxx）——同为字符串，契约不变，排障可读。
//
// 覆盖清单（基础档 39 粒，缺一即判据抓空）：
//   缺父孤儿×2        g-孤1 / g-孤2（上级 null → 未归属伪组，P0-0 裁决⑤：原生接受不修数据）
//   直挂特性×2        g-直 / g-越B（上级 F-2，不经专项——孤儿契约的另一形）
//   悬空依赖 ref×1    g-悬 → GHOST-404（哪个册都查不到 ⇒ 边照发，from=外:GHOST-404 悬空外部端点，
//                     外部:true——P2 依赖线画半截线+空心端点符）
//   冲突边×1          g-冲A→g-冲B（后继计划开始早于前置计划完成 ⇒ 服务端 冲突:true，P2 判据④⑥）
//   自由文本单号×1    g-文「（无单·直接落码）」（库里实证形，判据⑧ 单号闸）
//   同刻钟并发子单×20 g-c01..c20（S-1 下，08-24T14:00 同刻起同刻止，判据④ rollup 泳道）
//   越线待重判×2      g-越A（S-1）/ g-越B（直挂 F-2）——两分支；状态=计划 ∧ 计划开始≤现在(12:00)
//   完成×3            g-完1..3（board 归档态对拍；g-完1 兼作 6h 宽度对照条）
//   超长工期 30h×1    g-长（08-23T08:00 → 08-24T14:00，判据⑥ 24h 截断）
//   循环依赖三角×1    g-环1→g-环2→g-环3→g-环1（边状态=环，S-2 下）
//   跨项目外部依赖×1  g-外 → TF-3（边.外部=true）
//   另：未排期×1      g-欠（无计划开始，判据⑨ 欠账区）
//   另：纯未来分支×2  g-远1/g-远2（S-4，08-30 起——判据③ 默认折叠的反例，F-4 分支不许活跃）
//
// 规模档：造台账() = 基础档（全展开树行估 49）；造台账(80/200/500) 以「专项+9 粒」模板块克隆放大。
//   克隆块只挂 F-1..F-3——**F-4 永远保持非活跃分支**，判据③ 的反例不许被克隆冲掉。
//   克隆粒全部 已成单∧计划开始(09:00)≤现在 ⇒ 活跃分支默认展开到底，500 档默认可见行即上 500。
const schedule = require('../../lib/pm/schedule');

const 现在 = '2026-08-24T12:00';   // 判据的统一时钟（选项.现在 注入，别让判据依赖真实墙钟）
const 今日 = '2026-08-24';
const 单号形 = /^[A-Za-z]+-\d+$/;  // P0-0 裁决③ 的成链闸，与岛同一条正则

function 造台账(行数) {
  // ── 第一层：管线（/api/pipelines 形：{id, ...fm}）──
  const 管线 = [
    { id: 'P-1', 名称: '地图系统', 阶段: 'L1', 状态: '活跃', 开线时间: '2026-08-01T08:00:00.000Z' },
    { id: 'P-2', 名称: '引擎底座', 阶段: 'L0', 状态: '活跃', 开线时间: '2026-08-01T08:00:00.000Z' },
  ];

  // ── 第三层：专项骨架（/api/specials 聚合形；子单/进度 在收尾按 粒们 回填）──
  const 造专项 = (id, 名称, 特性id, 管线id) => ({
    id, 名称, 目标: `${名称}——合成台账`, 状态: '进行',
    管线: 管线id, 特性: 特性id, 项目: 'TK', 单号前缀: 'TK',
    类型: null, 完成定义: null, 别名: [], 立项时间: '2026-08-10T08:00:00.000Z',
    收口时间: null, 收口报告: null, 关账时间: null, 关账签字: null,
    子单: [], 进度: { 总数: 0, 落袋: 0, 归档: 0, 废弃: 0, 在办: 0, 未起: 0, 百分比: 0 },
    预算: { 预计h: 0, 实耗h: 0, 预计token: 0, 实耗token: 0, 偏差pct: null }, 基线: null,
  });
  const 专项 = [
    造专项('S-1', '并发泳道样本', 'F-1', 'P-1'),   // rollup 判据：20 并发 + 越线A
    造专项('S-2', '依赖花样样本', 'F-1', 'P-1'),   // 环三角 + 悬空 + 外部依赖（纯未来 ⇒ 默认折叠）
    造专项('S-3', '完成与超长样本', 'F-3', 'P-2'), // 完成×3 + 超长 30h + 自由文本单号 + 判定锁
    造专项('S-4', '远期储备样本', 'F-4', 'P-2'),   // 纯未来分支：判据③ 默认折叠的反例
  ];

  // ── 第四层：工单粒（/api/schedule 现态形，字段集对拍 lib/pm/schedule.规范粒 的 值 形）──
  let 序 = 0;
  const 粒 = [];
  const 造粒 = (id, o) => {
    const g = {
      粒ID: id, 批: '', 序: ++序, 题: o.题 || id, 状态: o.状态 || '已成单',
      型: '工单', 上级: o.上级 !== undefined ? o.上级 : null,
      项目: 'TK', 管线: o.管线 || null,
      依赖: o.依赖 || [], 池衡建议: null, 预估单元: o.预估单元 || null,
      计划开始: o.计划开始 || null, 计划完成: o.计划完成 || null, 工期天: null,
      // 基线缺省=计划（首次排期即立基线，同 schedule.规范粒）；判定锁粒显式给分叉基线
      基线开始: o.基线开始 !== undefined ? o.基线开始 : (o.计划开始 || null),
      基线完成: o.基线完成 !== undefined ? o.基线完成 : (o.计划完成 || null),
      就绪: false, 来源: '合成台账', 单号: o.单号 !== undefined ? o.单号 : null,
      版本号: 1, 登记时刻: '2026-08-20T09:00:00.000Z',
      更新时刻: o.更新时刻 || '2026-08-23T09:00:00.000Z', 末次操作者: '项管',
    };
    // 判定=服务端下发（真调唯一实现，别在夹具里手搓一套算术）；判定锁粒显式覆写
    g.判定 = o.判定 || schedule.工期判定(g, { 今日 });
    粒.push(g);
    return g;
  };

  // S-1：同刻钟并发 20 张（同起同止 ⇒ 全量叠压，判据④ 的极端形）
  for (let i = 1; i <= 20; i++) {
    造粒(`g-c${String(i).padStart(2, '0')}`, {
      题: `并发件${i}`, 上级: 'S-1', 状态: '已成单', 单号: `TK-${300 + i}`,
      计划开始: '2026-08-24T14:00', 计划完成: '2026-08-24T16:00',
    });
  }
  // 越线A：计划态 ∧ 计划开始 10:00 ≤ 现在 12:00 ⇒ 越线待重判；14:00-15:00 与并发窗叠压，抢泳道
  造粒('g-越A', { 题: '越线甲', 上级: 'S-1', 状态: '计划',
    计划开始: '2026-08-24T10:00', 计划完成: '2026-08-24T15:00' });

  // S-2：依赖花样（全排在未来 ⇒ 分支不活跃，默认折叠——判据②③ 都靠这个反差）
  造粒('g-环1', { 题: '环甲', 上级: 'S-2', 状态: '已成单', 单号: 'TK-331',
    计划开始: '2026-08-25T09:00', 计划完成: '2026-08-25T12:00', 依赖: [{ ref: 'g-环2', 规则: '全部完成' }] });
  造粒('g-环2', { 题: '环乙', 上级: 'S-2', 状态: '已成单', 单号: 'TK-332',
    计划开始: '2026-08-25T13:00', 计划完成: '2026-08-25T16:00', 依赖: [{ ref: 'g-环3', 规则: '全部完成' }] });
  造粒('g-环3', { 题: '环丙', 上级: 'S-2', 状态: '已成单', 单号: 'TK-333',
    计划开始: '2026-08-26T09:00', 计划完成: '2026-08-26T12:00', 依赖: [{ ref: 'g-环1', 规则: '全部完成' }] });
  造粒('g-悬', { 题: '悬空依赖件', 上级: 'S-2', 状态: '已成单', 单号: 'TK-334',
    计划开始: '2026-08-26T13:00', 计划完成: '2026-08-26T15:00', 依赖: [{ ref: 'GHOST-404', 规则: '全部完成' }] });
  造粒('g-外', { 题: '跨项目依赖件', 上级: 'S-2', 状态: '已成单', 单号: 'TK-335',
    计划开始: '2026-08-27T09:00', 计划完成: '2026-08-27T11:00', 依赖: [{ ref: 'TF-3', 规则: '任一完成' }] });
  // 冲突边样本（P2 判据④⑥）：g-冲B 计划开始(15:00) 早于前置 g-冲A 计划完成(17:00) ⇒ 服务端判 冲突:true。
  // 两粒全排未来（08-27）——S-2 分支保持非活跃，不动 P0 判据③ 的默认折叠反差。
  造粒('g-冲A', { 题: '冲突前置件', 上级: 'S-2', 状态: '已成单', 单号: 'TK-336',
    计划开始: '2026-08-27T13:00', 计划完成: '2026-08-27T17:00' });
  造粒('g-冲B', { 题: '冲突后继件', 上级: 'S-2', 状态: '已成单', 单号: 'TK-337',
    计划开始: '2026-08-27T15:00', 计划完成: '2026-08-27T19:00', 依赖: [{ ref: 'g-冲A', 规则: '全部完成' }] });

  // S-3：完成×3（g-完1 兼 6h 对照条）+ 超长 30h + 自由文本单号 + 判定锁
  造粒('g-完1', { 题: '完成甲', 上级: 'S-3', 状态: '完成', 单号: 'TK-401',
    计划开始: '2026-08-23T08:00', 计划完成: '2026-08-23T14:00', 更新时刻: '2026-08-23T13:30:00.000Z' });
  造粒('g-完2', { 题: '完成乙', 上级: 'S-3', 状态: '完成', 单号: 'TK-402',
    计划开始: '2026-08-22T09:00', 计划完成: '2026-08-22T15:00', 更新时刻: '2026-08-22T15:00:00.000Z' });
  造粒('g-完3', { 题: '完成丙', 上级: 'S-3', 状态: '完成', 单号: 'TK-403',
    计划开始: '2026-08-22T15:00', 计划完成: '2026-08-23T08:00', 更新时刻: '2026-08-23T08:00:00.000Z' });
  造粒('g-长', { 题: '超长件三十小时', 上级: 'S-3', 状态: '已成单', 单号: 'TK-410',
    计划开始: '2026-08-23T08:00', 计划完成: '2026-08-24T14:00' }); // 30h：判据⑥ 截断；在途∧已开始 ⇒ S-3 活跃
  造粒('g-文', { 题: '自由文本单号件', 上级: 'S-3', 状态: '已成单', 单号: '（无单·直接落码）',
    计划开始: '2026-08-23T10:00', 计划完成: '2026-08-23T12:00' }); // 库里实证形：判据⑧ 不成链
  // 判定锁（判据⑦ 的靶）：服务端判定与前端可私算值**故意分叉**——
  //   私算 延期 = 计划完成(08-23) − 基线完成(08-21) = 2 天；服务端下发 5（案外知情：如停表补偿期扣回）
  //   私算 超期 = 今日(08-24) 已过计划完成(08-23) ⇒ 超期；服务端下发 超期:false、需重排:false
  // 悬浮卡/行标必须逐字段跟服务端走；一旦前端自己算 e−基线，此粒判据必红。
  造粒('g-判锁', { 题: '判定锁·服务端≠私算', 上级: 'S-3', 状态: '已成单', 单号: 'TK-420',
    计划开始: '2026-08-22T09:00', 计划完成: '2026-08-23T09:00',
    基线开始: '2026-08-21T09:00', 基线完成: '2026-08-21T09:00',
    判定: { 已排期: true, 计划开始: '2026-08-22', 计划完成: '2026-08-23',
      基线开始: '2026-08-21', 基线完成: '2026-08-21', 工期天: null,
      延期天: 5, 延期: true, 余量天: 0, 超期: false, 超期天: 0,
      完成日: null, 超期完成: false, 超期完成天: null, 需重排: false } });

  // F-2 直挂（不经专项）：在途一张 + 越线B 一张
  造粒('g-直', { 题: '直挂在途件', 上级: 'F-2', 状态: '已成单', 单号: 'TK-350',
    计划开始: '2026-08-24T09:00', 计划完成: '2026-08-24T11:00' });
  造粒('g-越B', { 题: '越线乙', 上级: 'F-2', 状态: '计划',
    计划开始: '2026-08-24T08:00', 计划完成: '2026-08-24T10:00' });
  // 未排期（判据⑨ 欠账区）：有归属没排期——不进树，入欠账
  造粒('g-欠', { 题: '未排期欠账件', 上级: 'F-2', 状态: '计划' });

  // 缺父孤儿×2（未归属伪组）：g-孤1 已开始 ⇒ 伪组分支活跃、默认展开（判据① 要看得见孤儿行）
  造粒('g-孤1', { 题: '孤儿甲', 上级: null, 状态: '已成单', 单号: 'TK-360',
    计划开始: '2026-08-24T09:00', 计划完成: '2026-08-24T11:00' });
  造粒('g-孤2', { 题: '孤儿乙', 上级: null, 状态: '计划',
    计划开始: '2026-08-26T09:00', 计划完成: '2026-08-26T10:00' });

  // S-4：纯未来分支（判据③ 反例——F-4 整支默认折在特性层）
  造粒('g-远1', { 题: '远期甲', 上级: 'S-4', 状态: '计划',
    计划开始: '2026-08-30T09:00', 计划完成: '2026-08-30T12:00' });
  造粒('g-远2', { 题: '远期乙', 上级: 'S-4', 状态: '计划',
    计划开始: '2026-08-30T13:00', 计划完成: '2026-08-30T16:00' });

  // ── 规模档放大：克隆「专项 + 9 已排期粒」模板块，序号编排，直到全展开树行估过档 ──
  // 目标加 40 行余量：S-2/S-4 等默认折叠分支会藏掉几行，余量保证**默认可见行**也过档（判据⑩ 的分母）。
  if (行数) {
    const 目标 = Number(行数) + 40;
    const 树行 = () => 2 + 4 + 专项.length + 粒.filter((g) => g.计划开始 || g.计划完成).length + 1; // 管线+特性+专项+已排期粒+未归属伪组行
    for (let n = 1; 树行() < 目标; n++) {
      const sid = `S-${900 + n}`;
      const fid = `F-${(n % 3) + 1}`; // 只挂 F-1..F-3：F-4 必须保持非活跃分支
      const pid = fid === 'F-3' ? 'P-2' : 'P-1';
      专项.push(造专项(sid, `克隆专项${n}`, fid, pid));
      for (let j = 1; j <= 9; j++) {
        造粒(`g-放${n}-${j}`, { 题: `放大件${n}-${j}`, 上级: sid, 状态: '已成单',
          单号: `TK-9${String(n).padStart(2, '0')}${j}`,
          计划开始: '2026-08-24T09:00', 计划完成: '2026-08-24T11:00' }); // 已开始∧未完 ⇒ 活跃分支，默认展开
      }
    }
  }

  // ── 第二层：特性（/api/features 聚合形；专项摘要/计数按上面两层如实回填）──
  const 特性 = [
    { id: 'F-1', 名称: '城池布点', 管线: 'P-1' },
    { id: 'F-2', 名称: '图例与直挂', 管线: 'P-1' },
    { id: 'F-3', 名称: '寻路底盘', 管线: 'P-2' },
    { id: 'F-4', 名称: '远期储备', 管线: 'P-2' },
  ].map((f) => {
    const 子专项 = 专项.filter((s) => s.特性 === f.id).map((s) => ({ id: s.id, 名称: s.名称, 状态: s.状态 }));
    const 直挂 = 粒.filter((g) => g.上级 === f.id);
    return { id: f.id, 名称: f.名称, 管线: f.管线, 状态: '活跃', 边界: `${f.名称}——合成台账用`, 提请人: '项管',
      专项数: 子专项.length, 专项: 子专项, 直挂单数: 直挂.length, 单数: 直挂.length, 落袋: 0, 百分比: 0 };
  });

  // ── 专项.子单 与 进度 回填（聚合快照形：只收有规整单号的，同 specials.子单 只见真工单）──
  const 板态 = (g) => (g.状态 === '完成' ? '归档' : '在途');
  for (const s of 专项) {
    const kids = 粒.filter((g) => g.上级 === s.id && g.单号 && 单号形.test(g.单号));
    s.子单 = kids.map((g) => ({ id: g.单号, title: g.题, state: 板态(g), 职能: '策划', 单型: null,
      优先级: 'P1', 管线: s.管线, 依赖: null, 预计时间: null, 预计token: null,
      实耗h: null, 实耗token: null, 落袋: g.状态 === '完成', 挂起: null, 返工自: null, 推翻自: null, 归档原因: null }));
    const 落袋 = s.子单.filter((k) => k.落袋).length;
    s.进度 = { 总数: s.子单.length, 落袋, 归档: 落袋, 废弃: 0, 在办: s.子单.length - 落袋, 未起: 0,
      百分比: s.子单.length ? Math.round(100 * 落袋 / s.子单.length) : 0 };
  }

  // ── board单（/api/board 的 board 形：state→数组，fm.特性 已补格）──
  const 全态 = ['待审', '待派', '待处理', '待重派', '在途', '初检', '核查', '仲裁', '完成', '归档', '挂起', '废弃'];
  const board单 = Object.fromEntries(全态.map((s) => [s, []]));
  const 特性of = (g) => {
    if (!g.上级) return null;
    if (/^F-\d+$/.test(g.上级)) return g.上级;
    const s = 专项.find((x) => x.id === g.上级);
    return s ? s.特性 : null;
  };
  for (const g of 粒) {
    if (!g.单号 || !单号形.test(g.单号)) continue; // 自由文本单号成不了工单：board 只有真单
    board单[板态(g)].push({
      隐藏: false, id: g.单号, title: g.题, 职能: '策划', 优先级: 'P1', 规模: '单兵',
      QA: '关', 验收方式: '保留', 主办: null, 项目: 'TK', 阶段: null, 预计时间: null,
      父单: null, 依赖: null, 管线: g.管线, 父单类型: null,
      专项: /^S-\d+$/.test(g.上级 || '') ? g.上级 : null, 迁移至专项: null,
      特性: 特性of(g), // P0-0 裁决②补格（server.js:279）：直挂特性的工单靠它找到娘家
      领单时间: null, 交付时间: null, 滞留告警: false, 挂起: null,
      更新时间: g.更新时刻, 归档原因: null, 待引擎实证: false,
    });
  }

  // ── 边/边统计（P0-0 裁决④ 已落地：/api/schedule 增发＝真调 lib/pm/schedule-edges.边集，
  //    server.js:1275 同一条产线——夹具不手搓第二套解析，形状与服务端逐字节同源）。
  //    单册注入跨项目册：TF-3 实存于 TF 项目、opts.项目='TK' ⇒ 该边判外部（跨项目）；
  //    GHOST-404 哪个册都查不到 ⇒ from=外:GHOST-404 悬空外部端点（边照发，外部:true）——
  //    单靠正则分不出 悬空/外部，正是要下发已解析边集的原因。
  const scheduleEdges = require('../../lib/pm/schedule-edges');
  const 单册 = { 'TF-3': { 态: '在途', 项目: 'TF', 归档原因: null, 依赖: null } };
  const 图 = scheduleEdges.边集(粒, 单册, { 项目: 'TK' });
  const 边 = 图.边, 边统计 = 图.统计;

  // ── 判定索引：{粒ID → 服务端判定对象}，与 粒[i].判定 同源同对象（岛的唯一判定真值口）──
  const 判定 = Object.fromEntries(粒.map((g) => [g.粒ID, g.判定]));

  const 已排期粒数 = 粒.filter((g) => g.计划开始 || g.计划完成).length;
  return {
    管线, 特性, 专项, 粒, 边, 边统计, 判定, board单,
    统计: { 管线数: 管线.length, 特性数: 特性.length, 专项数: 专项.length,
      粒数: 粒.length, 已排期粒数,
      // 全展开树行估 = 管线+特性+专项+已排期粒+未归属伪组行（欠账粒不进树，判据⑩ 拿它当规模分母）
      树行估: 管线.length + 特性.length + 专项.length + 已排期粒数 + 1 },
  };
}

module.exports = { 造台账, 现在, 今日, 单号形 };
